-- Catalog schema and initial data for Mega Equipamentos.
-- Generated from src/app/data on 2026-05-20T20:35:24.635Z.

create extension if not exists pgcrypto;

create or replace function public.set_updated_at()
returns trigger
language plpgsql
as $$
begin
  new.updated_at = now();
  return new;
end;
$$;

do $$
begin
  if not exists (select 1 from pg_type where typname = 'catalog_status') then
    create type public.catalog_status as enum ('active', 'archived');
  end if;
end
$$;

create table if not exists public.categories (
  id integer primary key,
  nome text not null,
  slug text not null unique,
  name text not null default '',
  icone text not null default '',
  avatar text not null default '',
  avatar_hero text,
  avatar_card text,
  video text,
  objetivo text not null default '',
  status public.catalog_status not null default 'active',
  sort_order integer not null default 0,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

create table if not exists public.products (
  id integer generated by default as identity primary key,
  category_id integer not null references public.categories(id) on update cascade,
  nome text not null,
  slug text not null unique,
  avatar text,
  video text,
  descricao text not null default '',
  aplicacao text not null default '',
  tipo_de_servico text not null default '',
  periodo_de_locacao text not null default '',
  diferenciais text not null default '',
  status public.catalog_status not null default 'active',
  sort_order integer not null default 0,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

create table if not exists public.product_prices (
  product_id integer primary key references public.products(id) on delete cascade,
  daily_price_cents integer not null default 0 check (daily_price_cents >= 0),
  weekly_price_cents integer not null default 0 check (weekly_price_cents >= 0),
  fortnightly_price_cents integer not null default 0 check (fortnightly_price_cents >= 0),
  monthly_price_cents integer not null default 0 check (monthly_price_cents >= 0),
  currency text not null default 'BRL' check (currency = 'BRL'),
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

create index if not exists products_category_id_idx on public.products(category_id);
create index if not exists products_status_idx on public.products(status);
create index if not exists categories_status_idx on public.categories(status);

drop trigger if exists categories_set_updated_at on public.categories;
create trigger categories_set_updated_at
before update on public.categories
for each row execute function public.set_updated_at();

drop trigger if exists products_set_updated_at on public.products;
create trigger products_set_updated_at
before update on public.products
for each row execute function public.set_updated_at();

drop trigger if exists product_prices_set_updated_at on public.product_prices;
create trigger product_prices_set_updated_at
before update on public.product_prices
for each row execute function public.set_updated_at();

