on conflict (id) do update set
  category_id = excluded.category_id,
  nome = excluded.nome,
  slug = excluded.slug,
  avatar = excluded.avatar,
  video = excluded.video,
  descricao = excluded.descricao,
  aplicacao = excluded.aplicacao,
  tipo_de_servico = excluded.tipo_de_servico,
  periodo_de_locacao = excluded.periodo_de_locacao,
  diferenciais = excluded.diferenciais,
  sort_order = excluded.sort_order;

select setval(pg_get_serial_sequence('public.products', 'id'), greatest((select coalesce(max(id), 1) from public.products), 1));

insert into public.product_prices (product_id, daily_price_cents, weekly_price_cents, fortnightly_price_cents, monthly_price_cents, currency)
select id, 0, 0, 0, 0, 'BRL' from public.products
on conflict (product_id) do nothing;

alter table public.categories enable row level security;
alter table public.products enable row level security;
alter table public.product_prices enable row level security;

drop policy if exists "Public can read active categories" on public.categories;
create policy "Public can read active categories"
on public.categories for select
to anon, authenticated
using (status = 'active');

drop policy if exists "Authenticated can read all categories" on public.categories;
create policy "Authenticated can read all categories"
on public.categories for select
to authenticated
using (true);

drop policy if exists "Public can read active products" on public.products;
create policy "Public can read active products"
on public.products for select
to anon, authenticated
using (status = 'active');

drop policy if exists "Authenticated can read all products" on public.products;
create policy "Authenticated can read all products"
on public.products for select
to authenticated
using (true);

drop policy if exists "Authenticated can create products" on public.products;
create policy "Authenticated can create products"
on public.products for insert
to authenticated
with check (true);

drop policy if exists "Authenticated can update products" on public.products;
create policy "Authenticated can update products"
on public.products for update
to authenticated
using (true)
with check (true);

drop policy if exists "Public can read prices for active products" on public.product_prices;
create policy "Public can read prices for active products"
on public.product_prices for select
to anon, authenticated
using (exists (select 1 from public.products p where p.id = product_prices.product_id and p.status = 'active'));

drop policy if exists "Authenticated can read all prices" on public.product_prices;
create policy "Authenticated can read all prices"
on public.product_prices for select
to authenticated
using (true);

drop policy if exists "Authenticated can create prices" on public.product_prices;
create policy "Authenticated can create prices"
on public.product_prices for insert
to authenticated
with check (true);

drop policy if exists "Authenticated can update prices" on public.product_prices;
create policy "Authenticated can update prices"
on public.product_prices for update
to authenticated
using (true)
with check (true);
